Componente Responsabilidad Ejemplo Screen Gestión de estado y coordinación <code>HomeScreen.kt</code> Component UI reutilizable sin estado <code>CustomButton.kt</code> ViewModel Lógica de negocio y estado <code>HomeViewModel.kt</code> ✅ Screen (Stateful)✅ Component (Stateless) <pre><code>@Composable
fun HomeScreen(
    viewModel: HomeViewModel = hiltViewModel()
) {
    val uiState by viewModel.uiState.collectAsState()

    HomeContent(
        uiState = uiState,
        onUserAction = viewModel::handleUserAction
    )
}
</code></pre> <pre><code>@Composable
fun HomeContent(
    uiState: HomeUiState,
    onUserAction: (UserAction) -&gt; Unit
) {
    Column {
        when (uiState) {
            is HomeUiState.Loading -&gt; LoadingIndicator()
            is HomeUiState.Success -&gt; SuccessContent(
                data = uiState.data,
                onItemClick = { onUserAction(UserAction.ItemClick(it)) }
            )
            is HomeUiState.Error -&gt; ErrorMessage(uiState.message)
        }
    }
}
</code></pre>

